const updateSubscription = `-- name: UpdateSubscription :one
UPDATE subscription
SET title           = COALESCE($1, title),
    owner_note      = COALESCE($2, owner_note),
    auth            = COALESCE($3, auth),
    credential_path = COALESCE($4, credential_path),
    windows         = COALESCE($5, windows),
    caps            = COALESCE($6, caps),
    reserve         = COALESCE($7, reserve),
    settings        = COALESCE($8, settings),
    account_group   = COALESCE($9, account_group),
    disabled_until  = CASE WHEN $10::bool THEN NULL
                           ELSE COALESCE($11, disabled_until) END,
    updated_at      = now()
WHERE key = $12
RETURNING id, key, provider, title, owner_note, auth, credential_path, windows, caps, reserve, settings, account_group, disabled_until, created_by, created_at, updated_at
`

type UpdateSubscriptionParams struct {
	Title          pgtype.Text        `json:"title"`
	OwnerNote      pgtype.Text        `json:"owner_note"`
	Auth           pgtype.Text        `json:"auth"`
	CredentialPath pgtype.Text        `json:"credential_path"`
	Windows        []byte             `json:"windows"`
	Caps           []byte             `json:"caps"`
	Reserve        pgtype.Int4        `json:"reserve"`
	Settings       []byte             `json:"settings"`
	AccountGroup   pgtype.Text        `json:"account_group"`
	ClearDisabled  bool               `json:"clear_disabled"`
	DisabledUntil  pgtype.Timestamptz `json:"disabled_until"`
	Key            string             `json:"key"`
}

// Partial update via COALESCE: NULL args leave the column unchanged. key and
// provider are immutable. disabled_until is cleared with clear_disabled.
func (q *Queries) UpdateSubscription(ctx context.Context, arg UpdateSubscriptionParams) (Subscription, error) {
	row := q.db.QueryRow(ctx, updateSubscription,
		arg.Title,
		arg.OwnerNote,
		arg.Auth,
		arg.CredentialPath,
		arg.Windows,
		arg.Caps,
		arg.Reserve,
		arg.Settings,
		arg.AccountGroup,
		arg.ClearDisabled,
		arg.DisabledUntil,
		arg.Key,
	)
	var i Subscription
	err := row.Scan(
		&i.ID,
		&i.Key,
		&i.Provider,
		&i.Title,
		&i.OwnerNote,
		&i.Auth,
		&i.CredentialPath,
		&i.Windows,
		&i.Caps,
		&i.Reserve,
		&i.Settings,
		&i.AccountGroup,
		&i.DisabledUntil,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

